# ---------------------------------------------------------------------
# Generic helpers
# ---------------------------------------------------------------------

def now_ist() -> datetime:
    return datetime.now(IST).replace(microsecond=0)


def day_bounds_utc(day_text: str) -> tuple[datetime, datetime]:
    d = date.fromisoformat(day_text)
    start_local = datetime.combine(d, time.min, tzinfo=IST)
    end_local = start_local + timedelta(days=1)
    return start_local.astimezone(timezone.utc), end_local.astimezone(timezone.utc)


def json_default(value: Any) -> Any:
    from bson import ObjectId
    if isinstance(value, ObjectId):
        return str(value)
    if isinstance(value, datetime):
        return value.isoformat()
    raise TypeError(f"Not JSON serialisable: {type(value)!r}")


def clean_doc(doc: dict[str, Any] | None) -> dict[str, Any] | None:
    if doc is None:
        return None
    return json.loads(json.dumps(doc, default=json_default))


def bad(message: str) -> ValueError:
    return ValueError(message)


def money(value: Any) -> float:
    return round(float(value or 0), 2)


def sku_product(sku: str) -> dict[str, Any]:
    p = BY_SKU.get(sku)
    if not p:
        raise bad(f"Unknown product: {sku}")
    return p


# ---------------------------------------------------------------------
# MongoDB
# ---------------------------------------------------------------------

_client: MongoClient | None = None
_db = None


def get_db():
    global _client, _db
    if not MONGO_URI:
        raise RuntimeError(
            "MONGO_URI is not configured. Add your MongoDB Atlas connection "
            "string to the environment variable MONGO_URI."
        )
    if _client is None:
        _client = MongoClient(
            MONGO_URI,
            serverSelectionTimeoutMS=7000,
            connectTimeoutMS=7000,
            socketTimeoutMS=15000,
        )
        _db = _client[MONGO_DB]
        _client.admin.command("ping")
        ensure_collections()
    return _db


def ensure_collections() -> None:
    assert _db is not None

    _db.products.create_index([("sku", ASCENDING)], unique=True)
    _db.orders.create_index([("order_no", ASCENDING)], unique=True)
    _db.orders.create_index([("created_at", DESCENDING)])
    _db.orders.create_index([("status", ASCENDING), ("created_at", DESCENDING)])
    _db.inventory_movements.create_index([("created_at", DESCENDING)])

    # Only seed catalog fields. Existing current stock is never overwritten.
    for p in PRODUCTS:
        _db.products.update_one(
            {"sku": p["sku"]},
            {
                "$setOnInsert": {
                    **p,
                    "current_stock": int(p["opening_stock"]),
                    "active": True,
                    "created_at": now_ist(),
                    "updated_at": now_ist(),
                }
            },
            upsert=True,
        )

    _db.settings.update_one(
        {"_id": "event"},
        {
            "$setOnInsert": {
                "event_name": EVENT_NAME,
                "event_date": EVENT_DATE,
                "currency": "INR",
                "created_at": now_ist(),
            }
        },
        upsert=True,
    )


def mongo_health() -> dict[str, Any]:
    try:
        db = get_db()
        db.command("ping")
        return {
            "ok": True,
            "database": MONGO_DB,
            "message": "MongoDB connected",
        }
    except Exception as exc:
        return {
            "ok": False,
            "database": MONGO_DB,
            "message": str(exc),
        }


# ---------------------------------------------------------------------
# Billing rules
# ---------------------------------------------------------------------

def normalize_cart_line(line: dict[str, Any]) -> dict[str, Any]:
    kind = str(line.get("kind", "single"))
    qty = int(line.get("qty", 0) or 0)
    if qty <= 0:
        raise bad("Quantity must be greater than zero.")

    if kind == "single":
        sku = str(line.get("sku", ""))
        p = sku_product(sku)
        return {
            "kind": "single",
            "sku": sku,
            "display_name": p["name"],
            "qty": qty,
            "unit": p["unit"],
            "unit_price": p["price"],
            "line_total": money(p["price"] * qty),
            "cost_total": money(p["cost_price"] * qty),
            "combo_detail": "",
            "consumption": [{"sku": sku, "qty": qty}],
        }

    if kind == "choco_combo_same":
        flavor = str(line.get("flavor", ""))
        if flavor not in {"chana", "peanuts"}:
            raise bad("Choose Chana or Peanuts for the same-flavour combo.")
        detail = f"2 {'Chana' if flavor == 'chana' else 'Peanuts'}"
        return {
            "kind": kind,
            "sku": "choco-pops",
            "display_name": "Choco Pops — Same",
            "qty": qty,
            "unit": "combo",
            "unit_price": 70.0,
            "line_total": money(70.0 * qty),
            "cost_total": money(12.0 * 2 * qty),
            "combo_detail": detail,
            "flavor": flavor,
            "consumption": [{"sku": "choco-pops", "qty": qty * 2}],
        }

    if kind == "choco_combo_different":
        return {
            "kind": kind,
            "sku": "choco-pops",
            "display_name": "Choco Pops — Different",
            "qty": qty,
            "unit": "combo",
            "unit_price": 70.0,
            "line_total": money(70.0 * qty),
            "cost_total": money(12.0 * 2 * qty),
            "combo_detail": "1 Chana + 1 Peanuts",
            "consumption": [{"sku": "choco-pops", "qty": qty * 2}],
        }

    raise bad(f"Unknown cart line type: {kind}")


def normalize_cart(items: list[dict[str, Any]]) -> dict[str, Any]:
    if not isinstance(items, list) or not items:
        raise bad("Bill is empty.")

    lines = [normalize_cart_line(x) for x in items]

    aggregate: dict[str, int] = {}
    for line in lines:
        for use in line["consumption"]:
            aggregate[use["sku"]] = aggregate.get(use["sku"], 0) + int(use["qty"])

    subtotal = money(sum(line["line_total"] for line in lines))
    return {
        "lines": lines,
        "consumption": [{"sku": sku, "qty": qty} for sku, qty in aggregate.items()],
        "subtotal": subtotal,
    }


def next_order_number(session=None) -> str:
    db = get_db()
    counter = db.counters.find_one_and_update(
        {"_id": "orders"},
        {"$inc": {"value": 1}},
        upsert=True,
        return_document=True,
        session=session,
    )
    n = int(counter.get("value", 1))
    return f"{EVENT_DATE.replace('-', '')}-{n:03d}"


def current_products(session=None) -> list[dict[str, Any]]:
    return list(
        get_db().products.find({"active": True}, {"_id": 0}).sort([("_id", ASCENDING)]),
    )


def apply_consumption(
    consumption: list[dict[str, Any]],
    order_no: str | None,
    reason: str,
    session=None,
    direction: int = -1,
) -> None:
    """
    direction=-1 sale; direction=+1 restore.
    Uses conditional stock updates to prevent overselling.
    """
    db = get_db()
    stamp = now_ist()

    for use in consumption:
        sku = use["sku"]
        qty = int(use["qty"])
        if qty <= 0:
            continue

        if direction < 0:
            updated = db.products.find_one_and_update(
                {"sku": sku, "active": True, "current_stock": {"$gte": qty}},
                {
                    "$inc": {"current_stock": -qty},
                    "$set": {"updated_at": stamp},
                },
                return_document=True,
                session=session,
            )
        else:
            updated = db.products.find_one_and_update(
                {"sku": sku, "active": True},
                {
                    "$inc": {"current_stock": qty},
                    "$set": {"updated_at": stamp},
                },
                return_document=True,
                session=session,
            )

        if not updated:
            p = db.products.find_one({"sku": sku}, session=session)
            available = int(p["current_stock"]) if p else 0
            raise bad(f"Not enough stock for {p['name'] if p else sku}. Available: {available}.")

        before = int(updated["current_stock"]) - (direction * qty)
        after = int(updated["current_stock"])

        db.inventory_movements.insert_one(
            {
                "created_at": stamp,
                "sku": sku,
                "item": updated["name"],
                "reason": reason,
                "delta_qty": direction * qty,
                "before_qty": before,
                "after_qty": after,
                "order_no": order_no,
                "event_date": EVENT_DATE,
            },
            session=session,
        )


def consume_to_product_docs(order: dict[str, Any]) -> list[dict[str, int | str]]:
    return [
        {"sku": str(x["sku"]), "qty": int(x["qty"])}
        for x in order.get("consumption", [])
    ]


# ---------------------------------------------------------------------
# Order operations — transactionally synced
# ---------------------------------------------------------------------

def create_order(payload: dict[str, Any]) -> dict[str, Any]:
    payment = str(payload.get("payment_mode", "Cash"))
    amount_paid = money(payload.get("amount_paid", 0))
    discount = money(payload.get("discount", 0))
    notes = str(payload.get("notes", ""))[:1000]

    if payment not in VALID_PAYMENTS:
        raise bad("Invalid payment mode.")

    normalized = normalize_cart(payload.get("items", []))
    subtotal = normalized["subtotal"]

    if discount < 0 or discount > subtotal:
        raise bad("Discount cannot be negative or greater than subtotal.")

    total = money(subtotal - discount)
    if amount_paid < total:
        raise bad(f"Amount received must be at least ₹{total:,.2f}.")

    change_due = money(amount_paid - total)
    stamp = now_ist()

    db = get_db()
    with _client.start_session() as session:
        with session.start_transaction():
            order_no = next_order_number(session)
            order = {
                "order_no": order_no,
                "created_at": stamp,
                "event_date": EVENT_DATE,
                "status": "completed",
                "payment_mode": payment,
                "subtotal": subtotal,
                "discount": discount,
                "total": total,
                "amount_paid": amount_paid,
                "change_due": change_due,
                "notes": notes,
                "items": normalized["lines"],
                "consumption": normalized["consumption"],
            }
            try:
                db.orders.insert_one(order, session=session)
            except DuplicateKeyError:
                raise bad("Bill number collision. Please retry the bill.")

            apply_consumption(
                normalized["consumption"],
                order_no,
                "sale",
                session=session,
                direction=-1,
            )

    order["_id"] = str(order["_id"])
    return clean_doc(order) or {}


def get_order(order_no: str) -> dict[str, Any] | None:
    return clean_doc(get_db().orders.find_one({"order_no": order_no}))


def edit_order(order_no: str, payload: dict[str, Any]) -> dict[str, Any]:
    payment = str(payload.get("payment_mode", "Cash"))
    amount_paid = money(payload.get("amount_paid", 0))
    discount = money(payload.get("discount", 0))
    notes = str(payload.get("notes", ""))[:1000]

    if payment not in VALID_PAYMENTS:
        raise bad("Invalid payment mode.")

    normalized = normalize_cart(payload.get("items", []))
    subtotal = normalized["subtotal"]

    if discount < 0 or discount > subtotal:
        raise bad("Discount cannot be negative or greater than subtotal.")

    total = money(subtotal - discount)
    if amount_paid < total:
        raise bad(f"Amount received must be at least ₹{total:,.2f}.")
    change_due = money(amount_paid - total)

    db = get_db()
    stamp = now_ist()

    with _client.start_session() as session:
        with session.start_transaction():
            old = db.orders.find_one({"order_no": order_no}, session=session)
            if not old:
                raise bad("Bill not found.")
            if old["status"] != "completed":
                raise bad("Only completed bills can be edited.")

            apply_consumption(
                old.get("consumption", []),
                order_no,
                "edit restore",
                session=session,
                direction=1,
            )
            apply_consumption(
                normalized["consumption"],
                order_no,
                "edited sale",
                session=session,
                direction=-1,
            )

            db.orders.update_one(
                {"_id": old["_id"]},
                {
                    "$set": {
                        "payment_mode": payment,
                        "subtotal": subtotal,
                        "discount": discount,
                        "total": total,
                        "amount_paid": amount_paid,
                        "change_due": change_due,
                        "notes": notes,
                        "items": normalized["lines"],
                        "consumption": normalized["consumption"],
                        "updated_at": stamp,
                    }
                },
                session=session,
            )

            updated = db.orders.find_one({"_id": old["_id"]}, session=session)

    return clean_doc(updated) or {}


def void_order(order_no: str) -> None:
    db = get_db()
    with _client.start_session() as session:
        with session.start_transaction():
            order = db.orders.find_one({"order_no": order_no}, session=session)
            if not order:
                raise bad("Bill not found.")
            if order["status"] == "voided":
                raise bad("Bill is already voided.")

            apply_consumption(
                order.get("consumption", []),
                order_no,
                "void restore",
                session=session,
                direction=1,
            )
            db.orders.update_one(
                {"_id": order["_id"]},
                {"$set": {"status": "voided", "voided_at": now_ist()}},
                session=session,
            )


def set_inventory(sku: str, new_stock: int, threshold: int) -> dict[str, Any]:
    if new_stock < 0 or threshold < 0:
        raise bad("Stock and low-stock threshold must be non-negative.")

    db = get_db()
    stamp = now_ist()

    with _client.start_session() as session:
        with session.start_transaction():
            product = db.products.find_one({"sku": sku}, session=session)
            if not product:
                raise bad("Inventory item not found.")

            old_stock = int(product["current_stock"])
            delta = int(new_stock) - old_stock

            db.products.update_one(
                {"sku": sku},
                {
                    "$set": {
                        "current_stock": int(new_stock),
                        "low_stock_threshold": int(threshold),
                        "updated_at": stamp,
                    }
                },
                session=session,
            )

            if delta:
                db.inventory_movements.insert_one(
                    {
                        "created_at": stamp,
                        "sku": sku,
                        "item": product["name"],
                        "reason": "manual stock adjustment",
                        "delta_qty": delta,
                        "before_qty": old_stock,
                        "after_qty": int(new_stock),
                        "order_no": None,
                        "event_date": EVENT_DATE,
                    },
                    session=session,
                )

            updated = db.products.find_one({"sku": sku}, session=session)

    return clean_doc(updated) or {}


