def orders_for_date(day_text: str) -> list[dict[str, Any]]:
    start, end = day_bounds_utc(day_text)
    rows = list(
        get_db().orders.find(
            {"created_at": {"$gte": start, "$lt": end}},
            {"_id": 0},
        ).sort("created_at", DESCENDING).limit(500)
    )
    return clean_doc({"rows": rows})["rows"]


def sold_qty_map(day_text: str | None = None) -> dict[str, int]:
    query: dict[str, Any] = {}
    if day_text:
        start, end = day_bounds_utc(day_text)
        query = {"created_at": {"$gte": start, "$lt": end}}

    result: dict[str, int] = {}
    for order in get_db().orders.find({**query, "status": "completed"}, {"items": 1}):
        for line in order.get("items", []):
            # Physical Choco Pops consumption is 2 pcs per combo,
            # while single-flavour sales are 1 pc each.
            kind = line.get("kind", "single")
            qty = int(line.get("qty", 0))
            if kind in {"choco_combo_same", "choco_combo_different"}:
                result["choco-pops"] = result.get("choco-pops", 0) + qty * 2
            else:
                sku = line.get("sku")
                if sku:
                    result[sku] = result.get(sku, 0) + qty
    return result


def dashboard(day_text: str) -> dict[str, Any]:
    start, end = day_bounds_utc(day_text)
    db = get_db()

    orders = list(
        db.orders.find(
            {"created_at": {"$gte": start, "$lt": end}, "status": "completed"},
            {"total": 1, "items": 1, "payment_mode": 1},
        )
    )

    revenue = money(sum(o.get("total", 0) for o in orders))
    bills = len(orders)
    avg_bill = money(revenue / bills) if bills else 0.0

    sold_map: dict[str, int] = {}
    top_rows: list[dict[str, Any]] = []

    for order in orders:
        for line in order.get("items", []):
            kind = line.get("kind", "single")
            qty = int(line.get("qty", 0))
            physical_qty = qty * 2 if kind.startswith("choco_combo") else qty
            key = line.get("display_name", "Unknown")
            sold_map[key] = sold_map.get(key, 0) + physical_qty
            top_rows.append(
                {
                    "name": key,
                    "qty": physical_qty,
                    "revenue": money(line.get("line_total", 0)),
                }
            )

    grouped: dict[str, dict[str, Any]] = {}
    for row in top_rows:
        g = grouped.setdefault(
            row["name"],
            {"name": row["name"], "qty": 0, "revenue": 0.0},
        )
        g["qty"] += row["qty"]
        g["revenue"] = money(g["revenue"] + row["revenue"])

    top_products = sorted(
        grouped.values(),
        key=lambda x: (-x["revenue"], x["name"]),
    )[:8]

    payment_map: dict[str, dict[str, Any]] = {}
    for o in orders:
        p = o.get("payment_mode", "Other")
        g = payment_map.setdefault(p, {"payment_mode": p, "amount": 0.0, "bills": 0})
        g["amount"] = money(g["amount"] + o.get("total", 0))
        g["bills"] += 1

    payments = sorted(payment_map.values(), key=lambda x: (-x["amount"], x["payment_mode"]))

    gross_profit = 0.0
    for order in orders:
        for line in order.get("items", []):
            gross_profit += float(line.get("line_total", 0)) - float(line.get("cost_total", 0))
    gross_profit = money(gross_profit)

    products = list(
        db.products.find({"active": True}, {"_id": 0}).sort("name", ASCENDING)
    )
    inventory_value = money(
        sum(float(p["current_stock"]) * float(p["cost_price"]) for p in products)
    )

    low_stock = [
        {
            "sku": p["sku"],
            "name": p["name"],
            "stock": int(p["current_stock"]),
            "threshold": int(p["low_stock_threshold"]),
            "unit": p["unit"],
        }
        for p in products
        if int(p["current_stock"]) <= int(p["low_stock_threshold"])
    ]
    low_stock.sort(key=lambda x: (x["stock"], x["name"]))

    return {
        "date": day_text,
        "revenue": revenue,
        "bills": bills,
        "avg_bill": avg_bill,
        "gross_profit": gross_profit,
        "inventory_value": inventory_value,
        "payments": payments,
        "top_products": top_products,
        "low_stock": low_stock,
    }


def inventory_rows() -> list[dict[str, Any]]:
    db = get_db()
    sold = sold_qty_map()
    rows = []
    for p in db.products.find({"active": True}, {"_id": 0}).sort("name", ASCENDING):
        row = dict(p)
        row["sold_qty"] = int(sold.get(p["sku"], 0))
        row["status"] = (
            "OUT OF STOCK"
            if int(p["current_stock"]) == 0
            else "LOW"
            if int(p["current_stock"]) <= int(p["low_stock_threshold"])
            else "OK"
        )
        rows.append(clean_doc(row))
    return rows


