# ---------------------------------------------------------------------
# Excel export
# Preserves the supplied workbook and writes live POS data into the
# three dedicated POS sheets created from that workbook.
# ---------------------------------------------------------------------

def col_letter(n: int) -> str:
    s = ""
    while n:
        n, rem = divmod(n - 1, 26)
        s = chr(65 + rem) + s
    return s


def excel_cell(row: int, col: int, value: Any, style: int | None = None) -> str:
    ref = f"{col_letter(col)}{row}"
    s_attr = f' s="{style}"' if style is not None else ""
    if value is None:
        return f'<x:c r="{ref}"{s_attr}/>'
    if isinstance(value, bool):
        return f'<x:c r="{ref}"{s_attr} t="b"><x:v>{1 if value else 0}</x:v></x:c>'
    if isinstance(value, (int, float)):
        return f'<x:c r="{ref}"{s_attr}><x:v>{value}</x:v></x:c>'
    text = xml_escape(str(value))
    return (
        f'<x:c r="{ref}"{s_attr} t="inlineStr">'
        f'<x:is><x:t xml:space="preserve">{text}</x:t></x:is></x:c>'
    )


def excel_sheet_xml_from_template(template_xml: bytes, headers: list[str], rows: list[list[Any]]) -> bytes:
    text = template_xml.decode("utf-8")
    # Remove any old sheetData but retain the template's cols, margins,
    # widths and other workbook formatting.
    new_rows = []
    new_rows.append(
        '<x:row r="1" ht="30" customHeight="1">'
        + "".join(excel_cell(1, i + 1, value, 108) for i, value in enumerate(headers))
        + "</x:row>"
    )
    for r_index, row in enumerate(rows, start=2):
        cells = []
        for c_index, value in enumerate(row, start=1):
            style = 114 if isinstance(value, (int, float)) else None
            cells.append(excel_cell(r_index, c_index, value, style))
        new_rows.append(f'<x:row r="{r_index}">' + "".join(cells) + "</x:row>")

    sheet_data = "<x:sheetData>" + "".join(new_rows) + "</x:sheetData>"
    replaced = re.sub(
        r"<x:sheetData>.*?</x:sheetData>",
        sheet_data,
        text,
        count=1,
        flags=re.S,
    )
    if replaced == text and "<x:sheetData>" not in text:
        replaced = text.replace(
            "<x:sheetFormatPr",
            sheet_data + "<x:sheetFormatPr",
            1,
        )
    return replaced.encode("utf-8")


def build_excel_report() -> bytes:
    template = base64.b64decode(EXCEL_TEMPLATE_B64)
    z_in = zipfile.ZipFile(io.BytesIO(template), "r")

    # The three POS sheets are sheet8.xml, sheet9.xml, sheet10.xml in the
    # embedded template produced from the supplied workbook.
    sales_headers = [
        "Bill No",
        "Date/Time",
        "Status",
        "Payment Mode",
        "Subtotal (INR)",
        "Discount (INR)",
        "Total (INR)",
        "Amount Paid (INR)",
        "Change (INR)",
        "Item",
        "Qty",
        "Unit",
        "Unit Price (INR)",
        "Line Total (INR)",
        "Cost (INR)",
        "Gross Profit (INR)",
        "Order Item Type",
        "Combo Detail",
    ]

    orders = list(
        get_db().orders.find({}, {"_id": 0}).sort("created_at", ASCENDING)
    )
    sales_rows: list[list[Any]] = []
    for o in orders:
        for line in o.get("items", []):
            sales_rows.append(
                [
                    o["order_no"],
                    o["created_at"],
                    o["status"],
                    o["payment_mode"],
                    o["subtotal"],
                    o["discount"],
                    o["total"],
                    o["amount_paid"],
                    o["change_due"],
                    line["display_name"],
                    line["qty"],
                    line["unit"],
                    line["unit_price"],
                    line["line_total"],
                    line["cost_total"],
                    money(line["line_total"] - line["cost_total"]),
                    line["kind"],
                    line.get("combo_detail", ""),
                ]
            )

    inv_headers = [
        "SKU",
        "Item",
        "Category",
        "Sale Price (INR)",
        "Cost Price (INR)",
        "Unit",
        "Opening Stock",
        "Current Stock",
        "Sold Qty",
        "Low Stock At",
        "Status",
        "Event Date",
        "Last Updated",
    ]
    inv_rows: list[list[Any]] = []
    sold = sold_qty_map()
    for p in get_db().products.find({"active": True}, {"_id": 0}).sort("name", ASCENDING):
        status = (
            "OUT OF STOCK"
            if p["current_stock"] == 0
            else "LOW"
            if p["current_stock"] <= p["low_stock_threshold"]
            else "OK"
        )
        inv_rows.append(
            [
                p["sku"],
                p["name"],
                p["category"],
                p["price"],
                p["cost_price"],
                p["unit"],
                p["opening_stock"],
                p["current_stock"],
                sold.get(p["sku"], 0),
                p["low_stock_threshold"],
                status,
                EVENT_DATE,
                p["updated_at"],
            ]
        )

    mov_headers = [
        "Date/Time",
        "SKU",
        "Item",
        "Reason",
        "Delta Qty",
        "Before Qty",
        "After Qty",
        "Bill No",
        "Event Date",
    ]
    mov_rows: list[list[Any]] = []
    for m in get_db().inventory_movements.find({}, {"_id": 0}).sort("created_at", ASCENDING):
        mov_rows.append(
            [
                m["created_at"],
                m["sku"],
                m["item"],
                m["reason"],
                m["delta_qty"],
                m["before_qty"],
                m["after_qty"],
                m.get("order_no") or "",
                m["event_date"],
            ]
        )

    out_buf = io.BytesIO()
    with zipfile.ZipFile(out_buf, "w", zipfile.ZIP_DEFLATED) as z_out:
        for info in z_in.infolist():
            data = z_in.read(info.filename)
            if info.filename == "xl/worksheets/sheet8.xml":
                data = excel_sheet_xml_from_template(data, sales_headers, sales_rows)
            elif info.filename == "xl/worksheets/sheet9.xml":
                data = excel_sheet_xml_from_template(data, inv_headers, inv_rows)
            elif info.filename == "xl/worksheets/sheet10.xml":
                data = excel_sheet_xml_from_template(data, mov_headers, mov_rows)
            z_out.writestr(info, data)

    z_in.close()
    return out_buf.getvalue()


def make_full_backup_zip() -> bytes:
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        z.writestr("sales.csv", export_sales_csv())
        z.writestr("inventory.csv", export_inventory_csv())
        z.writestr("inventory_movements.csv", export_movements_csv())
        z.writestr("summary.csv", export_summary_csv())
        z.writestr("event_report.xlsx", build_excel_report())

        orders = [
            clean_doc(o)
            for o in get_db().orders.find({}, {"_id": 0}).sort("created_at", ASCENDING)
        ]
        inventory = inventory_rows()
        movements = [
            clean_doc(m)
            for m in get_db().inventory_movements.find({}, {"_id": 0}).sort("created_at", ASCENDING)
        ]
        z.writestr(
            "backup.json",
            json.dumps(
                {
                    "event_name": EVENT_NAME,
                    "event_date": EVENT_DATE,
                    "exported_at": now_ist(),
                    "orders": orders,
                    "inventory": inventory,
                    "inventory_movements": movements,
                },
                default=json_default,
                ensure_ascii=False,
                indent=2,
            ).encode("utf-8"),
        )
    return buf.getvalue()


def reset_event_and_return_backup() -> bytes:
    """
    Export first, then atomically reset orders/movements and stock.
    The ZIP returned to the browser is the pre-reset record.
    """
    backup = make_full_backup_zip()

    db = get_db()
    with _client.start_session() as session:
        with session.start_transaction():
            db.orders.delete_many({}, session=session)
            db.inventory_movements.delete_many({}, session=session)
            for p in PRODUCTS:
                db.products.update_one(
                    {"sku": p["sku"]},
                    {
                        "$set": {
                            "current_stock": int(p["opening_stock"]),
                            "low_stock_threshold": int(p["low_stock_threshold"]),
                            "updated_at": now_ist(),
                        }
                    },
                    session=session,
                )
            db.counters.update_one(
                {"_id": "orders"},
                {"$set": {"value": 0}},
                upsert=True,
                session=session,
            )
    return backup


# ---------------------------------------------------------------------
# HTTP server
# ---------------------------------------------------------------------

def send_bytes(handler, status: int, body: bytes, content_type: str, filename: str | None = None) -> None:
    handler.send_response(status)
    handler.send_header("Content-Type", content_type)
    handler.send_header("Content-Length", str(len(body)))
    handler.send_header("Cache-Control", "no-store, no-cache, must-revalidate")
    handler.send_header("Access-Control-Allow-Origin", CORS_ORIGIN)
    handler.send_header("Vary", "Origin")
    handler.send_header("Pragma", "no-cache")
    if filename:
        handler.send_header("Content-Disposition", f'attachment; filename="{filename}"')
    handler.end_headers()
    handler.wfile.write(body)


class Handler(BaseHTTPRequestHandler):
    server_version = "EventPOS-Mongo/2.0"

    def read_json(self) -> dict[str, Any]:
        length = int(self.headers.get("Content-Length", "0"))
        raw = self.rfile.read(length) if length else b"{}"
        payload = json.loads(raw.decode("utf-8"))
        if not isinstance(payload, dict):
            raise bad("JSON body must be an object.")
        return payload

    def json(self, status: int, data: Any) -> None:
        send_bytes(
            self,
            status,
            json.dumps(data, ensure_ascii=False, default=json_default).encode("utf-8"),
            "application/json; charset=utf-8",
        )

    def error(self, status: int, message: str) -> None:
        self.json(status, {"ok": False, "error": message})

    def do_OPTIONS(self) -> None:
        self.send_response(204)
        self.send_header("Access-Control-Allow-Origin", CORS_ORIGIN)
        self.send_header("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.send_header("Access-Control-Max-Age", "600")
        self.send_header("Vary", "Origin")
        self.end_headers()

    def do_GET(self) -> None:
        parsed = urlparse(self.path)
        path = parsed.path
        qs = parse_qs(parsed.query)

        try:
            if path == "/":
                body = INDEX_PATH.read_bytes()
                # Index contains no server-side placeholders.
                send_bytes(self, 200, body, "text/html; charset=utf-8")
                return

            if path == "/favicon.ico":
                send_bytes(self, 204, b"", "text/plain")
                return

            if path == "/api/health":
                self.json(200, mongo_health())
                return

            if path == "/api/meta":
                self.json(
                    200,
                    {
                        "ok": True,
                        "event_name": EVENT_NAME,
                        "event_date": EVENT_DATE,
                        "currency": "₹",
                        "categories": CATEGORY_ORDER,
                    },
                )
                return

            if path == "/api/products":
                self.json(200, {"ok": True, "products": current_products()})
                return

            if path == "/api/dashboard":
                day_text = qs.get("date", [EVENT_DATE])[0]
                self.json(200, {"ok": True, **dashboard(day_text)})
                return

            if path == "/api/orders":
                day_text = qs.get("date", [EVENT_DATE])[0]
                self.json(200, {"ok": True, "orders": orders_for_date(day_text)})
                return

            if path.startswith("/api/orders/"):
                order_no = path.rsplit("/", 1)[1]
                order = get_order(order_no)
                if not order:
                    self.error(404, "Bill not found.")
                else:
                    self.json(200, {"ok": True, "order": order})
                return

            if path == "/api/export/sales.csv":
                send_bytes(
                    self,
                    200,
                    export_sales_csv(),
                    "text/csv; charset=utf-8",
                    "event_sales.csv",
                )
                return

            if path == "/api/export/inventory.csv":
                send_bytes(
                    self,
                    200,
                    export_inventory_csv(),
                    "text/csv; charset=utf-8",
                    "event_inventory.csv",
                )
                return

            if path == "/api/export/inventory-movements.csv":
                send_bytes(
                    self,
                    200,
                    export_movements_csv(),
                    "text/csv; charset=utf-8",
                    "inventory_movements.csv",
                )
                return

            if path == "/api/export/summary.csv":
                send_bytes(
                    self,
                    200,
                    export_summary_csv(),
                    "text/csv; charset=utf-8",
                    "event_summary.csv",
                )
                return

            if path == "/api/export/excel.xlsx":
                send_bytes(
                    self,
                    200,
                    build_excel_report(),
                    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    "event_report.xlsx",
                )
                return

            self.error(404, "Not found.")

        except Exception as exc:
            self.error(500, str(exc))

    def do_POST(self) -> None:
        parsed = urlparse(self.path)
        path = parsed.path

        try:
            if path == "/api/orders":
                order = create_order(self.read_json())
                self.json(201, {"ok": True, "order": order})
                return

            if path.startswith("/api/inventory/") and path.endswith("/stock"):
                sku = path[len("/api/inventory/") : -len("/stock")].strip("/")
                payload = self.read_json()
                result = set_inventory(
                    sku,
                    int(payload.get("current_stock")),
                    int(payload.get("low_stock_threshold")),
                )
                self.json(200, {"ok": True, "product": result})
                return

            if path == "/api/reset":
                backup = reset_event_and_return_backup()
                send_bytes(
                    self,
                    200,
                    backup,
                    "application/zip",
                    f"event_reset_backup_{EVENT_DATE}.zip",
                )
                return

            self.error(404, "Not found.")

        except (ValueError, TypeError, json.JSONDecodeError) as exc:
            self.error(400, str(exc))
        except Exception as exc:
            self.error(500, str(exc))

    def do_PUT(self) -> None:
        path = urlparse(self.path).path
        try:
            if path.startswith("/api/orders/"):
                order_no = path.rsplit("/", 1)[1]
                order = edit_order(order_no, self.read_json())
                self.json(200, {"ok": True, "order": order})
                return
            self.error(404, "Not found.")
        except (ValueError, TypeError, json.JSONDecodeError) as exc:
            self.error(400, str(exc))
        except Exception as exc:
            self.error(500, str(exc))

    def do_DELETE(self) -> None:
        path = urlparse(self.path).path
        try:
            if path.startswith("/api/orders/"):
                order_no = path.rsplit("/", 1)[1]
                void_order(order_no)
                self.json(200, {"ok": True})
                return
            self.error(404, "Not found.")
        except ValueError as exc:
            self.error(400, str(exc))
        except Exception as exc:
            self.error(500, str(exc))

    def log_message(self, fmt: str, *args: Any) -> None:
        print(f"[{now_ist().strftime('%H:%M:%S')}] {self.address_string()} - {fmt % args}")


def main() -> None:
    # Fail early and clearly on startup if Mongo is unavailable.
    if not MONGO_URI:
        print(
            "\nEVENT POS NOT STARTED\n"
            "MONGO_URI is missing.\n"
            "Set your MongoDB Atlas connection string, then run again.\n"
        )
        return

    try:
        get_db()
    except Exception as exc:
        print("\nEVENT POS NOT STARTED")
        print(f"MongoDB connection failed: {exc}")
        return

    server = ThreadingHTTPServer((HOST, PORT), Handler)
    print("\nEVENT POS — MongoDB edition")
    print(f"Event     : {EVENT_NAME}")
    print(f"Event date: {EVENT_DATE}")
    print(f"Database  : {MONGO_DB}")
    print(f"Open      : http://{HOST}:{PORT}")
    print("Data      : MongoDB (no local database file)")
    print("Press Ctrl+C to stop.\n")

    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nStopping Event POS...")
    finally:
        server.server_close()
        if _client:
            _client.close()


if __name__ == "__main__":
    main()
